/// <summary>
/// Enchaîne des opérations du domaine sur une même machine et un même module, et vérifie après chacune
/// le résultat et le stock contre le modèle. Vérifie aussi que la machine est sans mémoire : une machine
/// neuve, branchée sur un module neuf dans le même état, donne le même résultat.
/// </summary>
[Theory]
[InlineData(1)]
[InlineData(2)]
[InlineData(3)]
[InlineData(4)]
[InlineData(5)]
[InlineData(6)]
[InlineData(7)]
[InlineData(8)]
public void RandomSequences_MatchSpecification_StepByStep(int seed)
{
    var random = new Random(seed);
    var allStocks = AllStocks().ToArray();
    var amounts = Amounts().ToArray();
    var deposits = AllDeposits().ToArray();

    for (var run = 0; run < 200; run++)
    {
        var jammed = Jams[random.Next(Jams.Length)];
        var dispenser = new MoneyDispenser(allStocks[random.Next(allStocks.Length)], jammed);
        var machine = new CashMachine(dispenser);
        var account = A(5 * random.Next(0, 51), 10 * random.Next(0, 21));
        var trace = new List<string>();

        for (var step = 0; step < 30; step++)
        {
            var stock = dispenser.Stock;
            Operation operation = random.Next(2) == 0
                ? new Operation.Withdraw(amounts[random.Next(amounts.Length)])
                : new Operation.Deposit(deposits[random.Next(deposits.Length)]);

            var (expected, expectedStock) = operation switch
            {
                Operation.Withdraw w => ExpectedWithdraw(account, w.Amount, stock, FewestNotesBySpec(w.Amount, stock, jammed)),
                Operation.Deposit d => ExpectedDeposit(account, d.Notes, stock, jammed),
                _ => throw new InvalidOperationException(),
            };

            var fresh = new MoneyDispenser(stock, jammed);
            var freshResult = new CashMachine(fresh).Execute(account, operation);

            var result = machine.Execute(account, operation);
            trace.Add($"{account}, stock {stock}, {operation} → {result}, stock {dispenser.Stock}");

            var context = $"graine {seed}, essai {run}, bloquée {jammed?.ToString() ?? "aucune"}{Environment.NewLine}" +
                          string.Join(Environment.NewLine, trace);
            Assert.True(expected == result, $"attendu {expected}{Environment.NewLine}{context}");
            Assert.True(expectedStock == dispenser.Stock, $"stock attendu {expectedStock}{Environment.NewLine}{context}");
            Assert.True(jammed == dispenser.Jammed, context);
            Assert.True(freshResult == result, $"machine neuve : {freshResult}{Environment.NewLine}{context}");
            Assert.True(fresh.Stock == dispenser.Stock, $"module neuf : {fresh.Stock}{Environment.NewLine}{context}");

            // Le compte suit les résultats, sauf si un dépôt le fait sortir du domaine (solde > 250) :
            // on garde alors l'ancien compte, le stock restant celui du module.
            account = result.Account.Balance <= 250 ? result.Account : account;
        }
    }
}

/// <summary>
/// Conservation : sur toute une séquence, ce qui est entré moins ce qui est sorti égale l'écart de stock,
/// et l'écart de solde s'explique exactement par les dépôts, les retraits et les frais.
/// </summary>
[Fact]
public void RandomSequences_ConserveNotesAndMoney()
{
    var random = new Random(42);
// Toutes opérations
// ====================================================================================================

/// <summary>
/// La machine est sans mémoire : après une première opération, la suivante donne le même résultat et le même
/// stock qu'une machine neuve sur un module neuf qui aurait ce stock.
/// </summary>
[Property(Arbitrary = [typeof(Generateurs)], Replay = Graine, MaxTest = Cas)]
public void LaMachineEstSansMemoire(Situation situation, UneOperation premiere, Situation autre, UneOperation seconde)
{
    var compteSuivant = autre.Account;

    var dispenser = new MoneyDispenser(situation.Stock, situation.Jammed);
    var machine = new CashMachine(dispenser);
    machine.Execute(situation.Account, premiere.Operation);

    var neuve = situation.WithStock(dispenser.Stock).WithAccount(compteSuivant);
    var (attendu, stockAttendu) = neuve.Run(seconde.Operation);

    var result = machine.Execute(compteSuivant, seconde.Operation);

    Assert.Equal(attendu, result);
    Assert.Equal(stockAttendu, dispenser.Stock);
}

/// <summary>
/// Une suite d'opérations dans le domaine conserve billets et argent : le stock final est le stock de départ plus
/// les billets déposés moins les billets sortis, et le solde bouge des dépôts moins les retraits et les frais.
/// Le compte reste dans le domaine tant qu'on ne dépose pas au-delà de 250.
/// </summary>
[Property(Arbitrary = [typeof(Generateurs)], Replay = Graine, MaxTest = Cas)]
public void UneSuiteDOperationsConserveBilletsEtArgent(Situation situation, UneOperation[] operations)
{
    var dispenser = new MoneyDispenser(situation.Stock, situation.Jammed);
    var machine = new CashMachine(dispenser);
    var account = situation.Account;
    var (deposes, sortis, frais) = (NoteCounts.None, NoteCounts.None, 0);

    foreach (var operation in operations)
    {
        if (operation.Operation is Operation.Deposit d && account.Balance + d.Notes.Value > 250)
        {
            continue; // le solde sortirait du domaine
        }

        var result = machine.Execute(account, operation.Operation);
        Assert.NotEqual(AtmStatus.DispenserFault, result.Status);

        if (result.Status == AtmStatus.Ok && operation.Operation is Operation.Deposit depot)
        {
            deposes += depot.Notes;
        }

        sortis += result.Notes;
        frais += result.Fee;
        account = result.Account;

        Assert.True(DansLeDomaine(account), $"compte hors domaine : {account}");
        Assert.All(Domaine.Coupures, c => Assert.InRange(dispenser.Stock.Of(c), 0, 5));
    }

    Assert.Equal(situation.Stock + deposes - sortis, dispenser.Stock);
    Assert.Equal(situation.Account.Balance + deposes.Value - sortis.Value - frais, account.Balance);
    Assert.Equal(situation.Account.WithdrawnToday + sortis.Value, account.WithdrawnToday);
}

/// <summary>
/// Le résultat ne dépend que du compte, de l'opération et du module : rejouer la même opération sur un module
/// identique donne le même résultat et le même stock.
/// </summary>
[Property(Arbitrary = [typeof(Generateurs)], Replay = Graine, MaxTest = Cas)]
public void LeResultatEstDeterministe(Situation situation, UneOperation operation)
{
    var (premier, stockPremier) = situation.Run(operation.Operation);
    var (second, stockSecond) = situation.Run(operation.Operation);

    Assert.Equal(premier, second);
    Assert.Equal(stockPremier, stockSecond);
}

